import json

# Replace p1_say through p5_say in content
def replace_say_list(content, var_name, new_list):
    list_str = json.dumps(new_list, indent=4)
    pattern = rf'{var_name} = \[[^\]]*\]'
    return re.sub(pattern, lambda m: f'{var_name} = {list_str}', content, flags=re.DOTALL)

